mapper.select:
        SELECT *
		  FROM T_CD15_SCHEDULE_RESULT R
		 WHERE R.DEL_FLAG = '0'
		   AND R.Machine_Id = #{params.machineId,jdbcType = VARCHAR}
	       AND R.BIG_ROLL_CODE = #{params.bigRollCode,jdbcType = VARCHAR}
	       AND R.SCHEDULE_DATE = #{params.scheduleDate}
	       AND R.DATA_SOURCE = '0'/* 只有自动排程的记录需要重算 */

mapper.update:
MERGE INTO T_CD15_SCHEDULE_RESULT a USING (
SELECT #{schedule.dayProduceOrder1,jdbcType = DOUBLE} DAY_PRODUCE_ORDER1, #{schedule.nightProduceOrder1,jdbcType = DOUBLE} NIGHT_PRODUCE_ORDER1, #{schedule.id} ID FROM dual
) b ON (a.id = b.id) WHEN MATCHED THEN UPDATE SET a.DAY_PRODUCE_ORDER1 = b.DAY_PRODUCE_ORDER1, a.NIGHT_PRODUCE_ORDER1 = b.NIGHT_PRODUCE_ORDER1
